(function () {
  "use strict";

  var root = document.documentElement;
  var live = document.getElementById("live-region");
  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function announce(message) {
    if (!live) return;
    live.textContent = "";
    window.setTimeout(function () { live.textContent = message; }, 60);
  }

  /* ---------------- reading mode ---------------- */

  var modeButtons = Array.prototype.slice.call(document.querySelectorAll(".mode__btn"));

  function paintMode(mode, announceIt) {
    root.dataset.mode = mode;
    modeButtons.forEach(function (btn) {
      btn.setAttribute("aria-pressed", String(btn.dataset.mode === mode));
    });
    if (announceIt) {
      announce(mode === "night" ? "Night reading mode on." : "Day reading mode on.");
    }
  }

  paintMode(root.dataset.mode === "night" ? "night" : "day", false);

  modeButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      var next = btn.dataset.mode === "night" ? "night" : "day";
      paintMode(next, true);
      try { localStorage.setItem("margin-mode", next); } catch (e) {}
    });
  });

  var system = window.matchMedia("(prefers-color-scheme: dark)");
  var onSystemChange = function (event) {
    var stored = null;
    try { stored = localStorage.getItem("margin-mode"); } catch (e) {}
    if (!stored) paintMode(event.matches ? "night" : "day", false);
  };
  if (system.addEventListener) system.addEventListener("change", onSystemChange);
  else if (system.addListener) system.addListener(onSystemChange);

  /* ---------------- subscription field ---------------- */

  var form = document.getElementById("subscribe-form");
  var input = document.getElementById("email");
  var msg = document.getElementById("email-msg");
  var PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

  var MESSAGES = {
    empty: "Add an email address so we know where to send it.",
    invalid: "That address doesn’t look right — check the @ and the domain.",
    ok: "Thanks — you’re on the list. Issue 14 goes to press on 6 November."
  };

  function show(state, text) {
    msg.textContent = text;
    msg.setAttribute("data-tone", state);
    input.setAttribute("aria-invalid", String(state === "error"));
    input.removeAttribute("data-state");
    if (state === "ok") input.setAttribute("data-state", "ok");
  }

  function validate(quiet) {
    var value = input.value.trim();
    if (!value) {
      if (!quiet) show("error", MESSAGES.empty);
      return false;
    }
    if (!PATTERN.test(value)) {
      if (!quiet) show("error", MESSAGES.invalid);
      return false;
    }
    return true;
  }

  if (form && input) {
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      if (validate(false)) {
        show("ok", MESSAGES.ok);
        announce(MESSAGES.ok);
        input.value = "";
        input.focus();
      } else {
        announce(msg.textContent);
        input.focus();
      }
    });

    input.addEventListener("blur", function () {
      if (input.value.trim()) validate(false);
    });

    input.addEventListener("input", function () {
      if (msg.getAttribute("data-tone") === "error") validate(false);
    });
  }

  /* ---------------- quiet reveal on scroll ---------------- */

  root.classList.add("js");

  if ("IntersectionObserver" in window && !reduceMotion) {
    var targets = document.querySelectorAll(
      ".issue__lede, .cover, .story--cover, .section-head, .story--side, .archive__item, .subscribe__offer, .subscribe__form, .footer"
    );
    Array.prototype.forEach.call(targets, function (el) { el.classList.add("reveal"); });

    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        entry.target.classList.add("is-in");
        observer.unobserve(entry.target);
      });
    }, { rootMargin: "0px 0px -12% 0px", threshold: 0.08 });

    Array.prototype.forEach.call(targets, function (el) { observer.observe(el); });
  }
})();

