  font-size: 0.9375rem;
  color: var(--ink);
  background: var(--paper);
  border: 0;
  border-bottom: 1px solid var(--ink);
  padding: 0.7rem 0.15rem;
  width: 100%;
  border-radius: 0;
  transition: border-color 0.25s var(--ease), background 0.25s var(--ease);
}
.field__input::placeholder { color: color-mix(in srgb, var(--ink) 38%, transparent); }
.field__input:hover { border-bottom-color: var(--oxide); }
.field__input[aria-invalid="true"] { border-bottom-color: var(--oxide); background: color-mix(in srgb, var(--oxide) 8%, var(--paper)); }
.field__input[data-state="ok"] { border-bottom-color: var(--ink); }

.field__msg {
  font-family: var(--sans);
  font-size: 0.8125rem;
  line-height: 1.45;
  letter-spacing: 0.01em;
  min-height: 1.2em;
  color: var(--ink-soft);
}
.field__msg[data-tone="error"] { color: var(--oxide); }
.field__msg[data-tone="ok"] { color: var(--ink); }
.field__msg[data-tone="ok"]::before {
  content: "";
  display: inline-block;
  width: 0.85rem;
  height: 0.45rem;
  border-left: 1px solid currentColor;
  border-bottom: 1px solid currentColor;
  transform: rotate(-45deg);
  margin-right: 0.5rem;
  vertical-align: 0.1em;
}

.btn {
  appearance: none;
  cursor: pointer;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: var(--paper);
  font-family: var(--sans);
  font-size: 0.75rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding: 0.95rem 1.4rem;
  justify-self: start;
  transition: background 0.25s var(--ease), color 0.25s var(--ease);
}
.btn:hover { background: var(--oxide); border-color: var(--oxide); }
.btn:active { transform: translateY(1px); }

.form__fineprint {
  font-size: 0.625rem;
  letter-spacing: 0.1em;
  color: var(--ink-soft);
  text-transform: none;
}

.footer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 2rem clamp(2rem, 5vw, 4rem);
  align-items: start;
  padding-bottom: clamp(2.5rem, 7vw, 5rem);
}
.wordmark--small { font-size: 1.75rem; }
.footer__line {
  font-size: var(--step-0);
  color: var(--ink-soft);
  margin-top: 0.6rem;
  max-width: 32ch;
}
.footer__cols { display: flex; flex-wrap: wrap; gap: 1.5rem clamp(1.5rem, 4vw, 3rem); }
.footer__cols dt {
  font-family: var(--sans);
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-soft);
  margin-bottom: 0.3rem;
}
.footer__cols dd { font-family: var(--mono); font-size: 0.8125rem; }
.footer__fine {
  grid-column: 1 / -1;
  padding-top: 1.5rem;
  border-top: 1px solid var(--hairline-2);
  color: var(--ink-soft);
  max-width: 60ch;
}

.cover__art path, .cover__art rect, .cover__art circle,
.mark path, .mark rect, .mark circle, .mark line {
  fill: none;
  stroke: currentColor;
  stroke-width: 1;
  stroke-linecap: square;
  vector-effect: non-scaling-stroke;
}
.ink-faint { opacity: 0.34; }
.accent { color: var(--oxide); }

.label {
  font-family: var(--mono);
  font-size: 16px;
  letter-spacing: 0.1em;
  fill: var(--ink-soft);
  stroke: none;
}
.label--accent { fill: var(--oxide); }
.label--minor { fill: var(--ink-soft); }

@media (max-width: 48rem) {
  .cover__art .label--minor { display: none; }
}

.stops circle, .trees circle {
  fill: var(--paper);
  stroke-width: 1.5;
}
.stops circle.accent { fill: var(--oxide); stroke: var(--oxide); }
.trees circle.accent { fill: color-mix(in srgb, var(--oxide) 22%, var(--paper)); }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

@media (max-width: 62rem) {
  .issue { grid-template-columns: minmax(0, 1fr); row-gap: 0; }
  .issue__lede { grid-area: auto; }
  .cover { grid-area: auto; margin-top: clamp(2.5rem, 8vw, 4rem); }
  .story--cover {
    grid-area: auto;
    grid-template-columns: minmax(0, 1fr);
    row-gap: 0;
  }
  .story--cover > *:not(.story__facts) { grid-column: 1; }
  .story__facts {
    grid-column: 1;
    grid-row: auto;
    display: flex;
    flex-wrap: wrap;
    gap: 0 2.5rem;
    border-left: 0;
    border-top: 1px solid var(--hairline-2);
    padding-left: 0;
    padding-top: 1.25rem;
    margin-top: 2rem;
  }
  .story__facts dt { width: 100%; }
  .story__facts dd { margin-bottom: 0; }
  .story__facts > div { min-width: 7rem; }

  .subscribe { grid-template-columns: minmax(0, 1fr); row-gap: clamp(2rem, 5vw, 3rem); }
  .stories { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: clamp(2rem, 5vw, 3rem); }
  .story--side:nth-child(3) { margin-top: 0; }
}

@media (max-width: 48rem) {
  .masthead { grid-template-columns: minmax(0, 1fr); align-items: start; }
  .masthead__aside { justify-content: flex-start; align-items: flex-start; }
  .mode { justify-items: start; }
  .archive__list { grid-template-columns: minmax(0, 1fr); row-gap: 0; }
  .archive__item { grid-template-columns: auto minmax(0, 1fr); }
  .archive__item + .archive__item {
    border-left: 0;
    border-top: 1px solid color-mix(in srgb, var(--paper) 22%, transparent);
    padding-left: 0;
    margin-top: 1.75rem;
    padding-top: 1.75rem;
  }
  .footer { grid-template-columns: minmax(0, 1fr); }
  .stories { grid-template-columns: minmax(0, 1fr); }
  .story--side:nth-child(2) { margin-top: 0; }
}

@media (max-width: 48rem) {
  .issue__numeral { font-size: 5.5rem; top: -0.6rem; right: -0.3rem; }
}

@media (max-width: 30rem) {
  .standfirst { font-size: var(--step-2); }
  .price { gap: 0.35rem 0.9rem; }
  .trim { display: none; }
}

@media (pointer: coarse) {
  .mode__btn { padding: 0.6rem 1rem; }
  .btn { padding: 1.05rem 1.5rem; }
}

@media print {
  body::after, .trim, .mode, .excerpt__toggle { display: none !important; }
  body { background: #fff; }
  .archive { background: #fff; color: #000; }
  .archive__num, .archive__season { color: #444; }
  .excerpt__body { display: block !important; }
}

