const fs = require('fs');
const src = fs.readFileSync('/tmp/claude-1000/-home-arda-projects-agent-evaluation/8413ce30-b544-4ae4-afd6-5f8333042ec1/scratchpad/agent-eval-step-5-preview/12-frontend-editorial/app.js','utf8');

function el(extra) {
  return Object.assign({
    dataset: {}, attrs: {}, textContent: '', value: '',
    listeners: {},
    getAttribute(k){ return this.attrs[k]; },
    setAttribute(k,v){ this.attrs[k]=v; },
    removeAttribute(k){ delete this.attrs[k]; },
    addEventListener(t,f){ (this.listeners[t]=this.listeners[t]||[]).push(f); },
    fire(t,e){ (this.listeners[t]||[]).forEach(f=>f(e||{preventDefault(){}})); },
    focus(){}, classList:{add(){},remove(){}}
  }, extra||{});
}

const root = el();
const live = el();
const day = el({dataset:{mode:'day'}});
const night = el({dataset:{mode:'night'}});
const input = el({value:''});
const msg = el();
const form = el();
const byId = {'live-region':live, 'subscribe-form':form, 'email':input, 'email-msg':msg};

global.window = {
  matchMedia: () => ({matches:false, addEventListener(){}, addListener(){}}),
  setTimeout: (f)=>f()
};
global.localStorage = { _s:{}, getItem(k){return this._s[k]||null;}, setItem(k,v){this._s[k]=v;} };
global.document = {
  documentElement: root,
  getElementById: (id)=> byId[id] || null,
  querySelectorAll: (sel)=> sel === '.mode__btn' ? [day, night] : [],
};

eval(src);

const results = [];
function check(name, cond){ results.push((cond?'PASS':'FAIL')+' '+name); }

// --- reading mode ---
check('initial mode day', root.dataset.mode === 'day');
check('day pressed, night not', day.getAttribute('aria-pressed')==='true' && night.getAttribute('aria-pressed')==='false');
night.fire('click');
check('night switches', root.dataset.mode === 'night');
check('aria swaps', day.getAttribute('aria-pressed')==='false' && night.getAttribute('aria-pressed')==='true');
check('localStorage saved', global.localStorage.getItem('margin-mode')==='night');
check('announced', live.textContent.indexOf('Night') > -1);
day.fire('click');
check('day switches back', root.dataset.mode === 'day');

// --- email validation ---
function submit(value){
  input.value = value;
  msg.attrs = {}; msg.textContent='';
  input.attrs['aria-invalid']='false';
  form.fire('submit');
  return {msg: msg.textContent, tone: msg.getAttribute('data-tone'), invalid: input.getAttribute('aria-invalid')};
}
let r = submit('');
check('empty -> error', r.tone==='error' && /email address/i.test(r.msg) && r.invalid==='true');
r = submit('nope');
check('malformed -> error', r.tone==='error' && /@/.test(r.msg) && r.invalid==='true');
r = submit('reader@margin.example');
check('valid -> ok', r.tone==='ok' && /on the list/i.test(r.msg) && r.invalid==='false');
check('field cleared on success', input.value === '');
check('data-state ok set', input.getAttribute('data-state')==='ok');
r = submit('  spaced@mail.co ');
check('whitespace trimmed ok', r.tone==='ok');
r = submit('a@b');
check('short tld -> error', r.tone==='error');
// live revalidation while typing
input.value='bad'; msg.setAttribute('data-tone','error');
input.fire('input');
check('revalidates on input while error', msg.getAttribute('data-tone')==='error');
input.value='good@mail.com'; input.fire('input');
check('clears error when fixed', msg.getAttribute('data-tone')==='ok');

console.log(results.join('\n'));
console.log(results.some(x=>x.startsWith('FAIL')) ? '\nSOME TESTS FAILED' : '\nALL TESTS PASSED');
EOF
